/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `order_created_notification` AFTER INSERT ON `don_hang` FOR EACH ROW INSERT INTO thong_bao (ma_tai_khoan,tieu_de,noi_dung,ma_don_hang) VALUES (NEW.ma_tai_khoan,'Đơn hàng mới',CONCAT('Đơn #',NEW.ma_don_hang,' đã được ghi nhận.'),NEW.ma_don_hang) */;;
