/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `order_status_notification` AFTER UPDATE ON `don_hang` FOR EACH ROW BEGIN IF OLD.trang_thai <> NEW.trang_thai THEN INSERT INTO thong_bao (ma_tai_khoan,tieu_de,noi_dung,ma_don_hang) VALUES (NEW.ma_tai_khoan,'Order update',CONCAT('Đơn #',NEW.ma_don_hang,': ', CASE NEW.trang_thai WHEN 'DaXacNhan' THEN 'Đã xác nhận' WHEN 'DangGiao' THEN 'Đang giao' WHEN 'DaGiao' THEN 'Đã giao' WHEN 'DaHuy' THEN 'Đã hủy' ELSE 'Chờ xác nhận' END),NEW.ma_don_hang); END IF; END */;;
