/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `contact_reply_notification` AFTER UPDATE ON `lien_he` FOR EACH ROW BEGIN IF NEW.phan_hoi IS NOT NULL AND NOT (OLD.phan_hoi <=> NEW.phan_hoi) AND NEW.ma_tai_khoan IS NOT NULL THEN INSERT INTO thong_bao (ma_tai_khoan,tieu_de,noi_dung) VALUES (NEW.ma_tai_khoan,'Contact reply',CONCAT('Cửa hàng đã phản hồi liên hệ: ',NEW.tieu_de)); END IF; END */;;
