DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_san_pham_delete`(IN p_id INT)
BEGIN
    DELETE FROM san_pham WHERE ma_san_pham = p_id;
    SELECT ROW_COUNT() AS affectedRows;
END ;;
